"""Validation rules migrated from legacy/account_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    """Return a column value, treating missing values and None as empty."""
    if row is None:
        return ""
    value = row.get(column, "")
    return "" if value is None else value


def _text(row: dict | None, column: str) -> str:
    """Return a text-column value using legacy missing-value semantics."""
    value = _value(row, column)
    return value if isinstance(value, str) else str(value)


def _number(value: Any) -> Decimal:
    """Coerce a NUMBER value, with an empty value becoming numeric zero."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _failure(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {"code": code, "message": message, "severity": severity}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate all applicable account rules in legacy rule-file order."""
    del today  # TODAY() is not used by these five rules.

    errors: list[dict] = []

    # ACC-001
    if event in ("INSERT", "UPDATE"):
        if len(_text(record, "ACCT_NM")) < 2:
            errors.append(
                _failure("E1001", "Account name too short")
            )

    # ACC-002
    if event in ("INSERT", "UPDATE"):
        if _text(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            errors.append(
                _failure("E1002", "Invalid account type")
            )

    # ACC-003
    if event in ("INSERT", "UPDATE"):
        ann_rev = _value(record, "ANN_REV")
        nvl_ann_rev = 0 if ann_rev == "" else ann_rev
        if _number(nvl_ann_rev) < 0:
            errors.append(
                _failure("E1003", "Annual revenue negative")
            )

    # ACC-004
    if event == "UPDATE":
        releases_hold = (
            _text(old, "CRED_HOLD") == "Y"
            and _text(record, "CRED_HOLD") == "N"
            and _number(_value(record, "CRED_LIMIT")) <= 0
        )
        if releases_hold:
            errors.append(
                _failure(
                    "E1004",
                    "Cannot release credit hold with zero credit limit",
                )
            )

    # ACC-005
    if event in ("INSERT", "UPDATE"):
        if len(_text(record, "REGION_CD")) != 3:
            errors.append(
                _failure(
                    "E1005",
                    "Region code must be 3 chars",
                    "WARN",
                )
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
